{"source":"text = cat('finance_report.txt')['file_content']
nums = []
for key in ['Revenue: $', 'Expenses: $', 'Profit: $']:
    idx = text.find(key)
    if idx != -1:
        start = idx + len(key)
        end = start
        while end < len(text) and text[end].isdigit():
            end += 1
        nums.append(float(text[start:end]))
mean_val = mean(nums)['result']
rounded = round_number(mean_val, 0)['result']
try:
    rm('statistics.txt')
except:
    pass
touch('statistics.txt')
print(str(int(rounded)))"}

